package main

import (
	"os"
	"path/filepath"
	"testing"
)

// Exercise the actual engine-output reader with a fake engine. No network
// requests or training games are generated by these tests.
func TestHardwareReportingWithCustomBackend(t *testing.T) {
	for _, tc := range []struct {
		name    string
		output  string
		enabled bool
		want    string
	}{
		{"cuda", "GPU: NVIDIA GeForce RTX 4060 Laptop GPU", true, "NVIDIA GeForce RTX 4060 Laptop GPU"},
		{"opencl", "Selected device: Test OpenCL GPU", true, "Test OpenCL GPU"},
		{"cpu", "BLAS backend", true, "None"},
		{"disabled", "GPU: NVIDIA GeForce RTX 4060 Laptop GPU", false, "Unknown"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			oldExe, oldGPU, oldReport, oldBackend := lc0Exe, gpuType, *report_gpu, *backopts
			defer func() {
				lc0Exe, gpuType, *report_gpu, *backopts = oldExe, oldGPU, oldReport, oldBackend
			}()
			lc0Exe = filepath.Join(t.TempDir(), "fake-lc0")
			if err := os.WriteFile(lc0Exe, []byte("#!/bin/sh\nprintf '%s\\n' '"+tc.output+"'\n"), 0700); err != nil {
				t.Fatal(err)
			}
			gpuType, *report_gpu = "Unknown", tc.enabled
			*backopts = "backend=cuda-auto,multi_stream=true,max_batch=256"
			wrapper := createCmdWrapper()
			wrapper.launch("unused-weights", "", []string{"selfplay"}, false)
			// Closing this channel confirms the output-reader goroutine completed.
			for range wrapper.gi {
			}
			if err := wrapper.Cmd.Wait(); err != nil {
				t.Fatal(err)
			}
			if gpuType != tc.want {
				t.Fatalf("GPU reporting = %q, want %q", gpuType, tc.want)
			}
			if params := getExtraParams(); params["gpu"] != tc.want || params["version"] != "34" {
				t.Fatalf("unexpected upload metadata: gpu=%q version=%q", params["gpu"], params["version"])
			}
		})
	}
}
